// Calcula la tasa de errores y el consumo de la última hora
const hace1h = Date.now() - 60 * 60 * 1000;
const filas = $input.all().map((i) => i.json).filter((r) => r && r.createdAt && new Date(r.createdAt).getTime() >= hace1h);
const total = filas.length;
const errores = filas.filter((r) => Number(r.http_status) >= 500 || String(r.resultado).startsWith('error')).length;
const tokens = filas.reduce((s, r) => s + (Number(r.tokens_estimados) || 0), 0);
const tasa = total ? errores / total : 0;
return [{ json: { total, errores, tasa_errores: Math.round(tasa * 100), tokens_ultima_hora: tokens, alertar: (total >= 5 && tasa > 0.2) || tokens > 20000 } }];

// Freno antes de enviar: el correo sale solo si pasa todas las reglas.
const d = $input.first().json || {};
const para = String(d.para || '').trim();
const asunto = String(d.asunto || '').trim();
const mensaje = String(d.mensaje || '').trim();
const motivos = [];

const emails = para.split(',').map((e) => e.trim()).filter(Boolean);
const EMAIL = /^[^\s@<>]+@[^\s@<>]+\.[a-z]{2,}$/i;
if (!emails.length) motivos.push('Falta el email del destinatario.');
else if (emails.some((e) => !EMAIL.test(e))) motivos.push('Hay un email con formato inválido.');
if (emails.length > 3) motivos.push('Más de 3 destinatarios: requiere aprobación humana.');
if (asunto.length < 3 || asunto.length > 150) motivos.push('El asunto está vacío o es demasiado largo.');
if (mensaje.length < 30) motivos.push('El mensaje está vacío o es demasiado corto.');
if (mensaje.length > 3000) motivos.push('El mensaje es demasiado largo.');
if (/no tengo informaci[oó]n suficiente|no estoy segur|no lo s[eé]|no puedo confirmar/i.test(mensaje)) motivos.push('El texto tiene frases de incertidumbre.');
if (/\[[^\]]{1,40}\]|\{\{|XXX|TODO|lorem ipsum/i.test(asunto + ' ' + mensaje)) motivos.push('El texto tiene marcadores sin completar.');
if (/(\$|USD|U\$S|ARS)\s?\d|\d+\s?(pesos|d[oó]lares)/i.test(mensaje)) motivos.push('Menciona montos: los precios los confirma una persona del equipo.');

return [{ json: { valido: motivos.length === 0, motivos, para: emails.join(', '), asunto, mensaje } }];
